        self.assertEqual(marker_state["phase"], "ACTIVE_SEEN")
        self.assertTrue(marker_state["active_seen"])
        self.assertEqual(comment_marker.buttons, [Button.B])

        green_victory = Command({"POKEMON_ZA_TEXT_GREEN_COMMENT"})
